responseFormat.typescriptTypesReference:
type Citation = {
commentId: number;
};

type Clause = {
text: string;
citations: Citation[];
};

type Sentence = {
clauses: Clause[];
};

type Paragraph = {
id: string; // e.g. "subject_and_positions"
title: string;
sentences: Sentence[];
};

type Subtask = {
id: string;
title: string;
paragraphs: Paragraph[];
};

polisAnalysisPrompt.example:
{
"id": "topic_scene_setting",
"title": "What This Topic Is About",
"paragraphs": [
{
"id": "subject_and_positions",
"title": "The Subject and the Positions on It",
"sentences": [
{
"clauses": [
{
"text": "The statements grouped under this topic concern whether short-term holiday lets harm host communities more than second homes do.",
"citations": [6]
}
]
},
{
"clauses": [
{
"text": "One position treats the two as different problems, arguing that a let which turns over every week removes a home from the village in a way a second home does not.",
"citations": [6, 9]
}
]
}
]
},
{
"id": "open_questions",
"title": "What the Group Has to Weigh",
"sentences": [
{
"clauses": [
{
"text": "The group has to decide whether the distinction changes what should be done, or whether both forms of non-resident ownership call for the same response.",
"citations": [6, 12]
}
]
}
]
}
]
}
